#unjoinedApp{--g:#1B5E20;--line:#DCE9DE;font:14px/1.5 Inter,'Segoe UI',sans-serif;color:#152418;background:#F3FAF4;min-height:90vh;border-radius:16px;overflow:hidden}#unjoinedApp *{box-sizing:border-box}#unjoinedApp h1,#unjoinedApp h2,#unjoinedApp h3{margin:0}#unjoinedApp .uj-header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 28px;color:white;background:linear-gradient(135deg,#0F3D1E,#1B5E20 70%,#2E7D32)}#unjoinedApp .uj-header h1{font-size:28px;color:white}#unjoinedApp .uj-header small{letter-spacing:2px;font-size:10px;color:#BFE3C4}#unjoinedApp .uj-header p{margin:4px 0}#unjoinedApp .uj-header a{color:white}#unjoinedApp .uj-body{padding:22px}#unjoinedApp .uj-filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px;background:white;padding:18px;border:1px solid var(--line);border-radius:14px}#unjoinedApp label{display:grid;gap:5px;font-size:12px;font-weight:600}#unjoinedApp input,#unjoinedApp select,#unjoinedApp button{font:inherit;border:1px solid var(--line);border-radius:8px;padding:9px 12px;min-height:38px;background:white;color:#152418}#unjoinedApp button{cursor:pointer;font-size:12px;font-weight:600}#unjoinedApp button:hover{background:#E8F5E9}#unjoinedApp button:disabled{opacity:.45;cursor:default}#unjoinedApp #ujApply{color:white;background:var(--g)}#unjoinedApp .uj-search{flex:1;min-width:220px}#unjoinedApp .uj-help{font-size:12px;color:#5F6F63;margin:12px 0}#unjoinedApp .uj-tools{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px}#unjoinedApp #ujCards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0 24px}#unjoinedApp .uj-card{display:grid;background:white;border:1px solid var(--line);border-top:4px solid var(--g);border-radius:12px;padding:18px;color:#152418;text-decoration:none}#unjoinedApp .uj-card strong{font-size:32px;color:var(--g)}#unjoinedApp section{background:white;border:1px solid var(--line);border-radius:14px;margin-bottom:24px;overflow:hidden;scroll-margin-top:20px}#unjoinedApp .uj-section-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;padding:16px 18px;border-bottom:1px solid var(--line)}#unjoinedApp h2{font-size:17px;color:var(--g)}#unjoinedApp .uj-section-head small{color:#5F6F63}#unjoinedApp .uj-count{background:#E8F5E9;border-radius:20px;padding:2px 10px}#unjoinedApp .uj-scroll{overflow:auto}#unjoinedApp table{width:100%;border-collapse:collapse;font-size:12px}#unjoinedApp th{background:#F3FAF4;color:#14501F;text-align:left;white-space:nowrap;padding:12px}#unjoinedApp td{padding:11px 12px;border-bottom:1px solid #edf3ee;vertical-align:top;min-width:95px}#unjoinedApp td small{display:block;color:#5F6F63}#unjoinedApp .uj-link{border:0;background:transparent;color:var(--g);text-align:left;padding:0;min-height:0;font-size:13px}#unjoinedApp .uj-avatar{width:40px;height:40px;object-fit:cover;border-radius:8px;float:left;margin-right:8px}#unjoinedApp .uj-badge{display:inline-block;background:#FFF3E0;color:#985300;border-radius:8px;padding:5px 8px;font-size:11px}#unjoinedApp .uj-paging{display:flex;gap:16px;justify-content:flex-end;align-items:center;padding:14px;font-size:12px}#unjoinedApp .uj-error{color:#C62828}#unjoinedApp dialog{width:min(1150px,95vw);max-height:90vh;padding:0;border:0;border-radius:14px;color:#152418}#unjoinedApp dialog::backdrop{background:rgba(5,25,10,.65)}#unjoinedApp .uj-dialog-head{position:sticky;top:0;z-index:1;background:#E8F5E9;padding:16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}#unjoinedApp #ujDetails{padding:22px}#unjoinedApp .uj-full-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 24px}#unjoinedApp .uj-full-grid>div{padding:10px;border:1px solid var(--line);border-radius:8px;overflow-wrap:anywhere}#unjoinedApp .uj-full-grid b{display:block;font-size:11px;color:#5F6F63}#unjoinedApp .uj-full-grid span{white-space:pre-wrap}#unjoinedApp .uj-wide{grid-column:1/-1}#unjoinedApp .uj-gallery{display:flex;gap:14px;flex-wrap:wrap;margin:14px 0 30px}#unjoinedApp .uj-gallery a{display:grid;gap:6px;max-width:220px;color:var(--g);overflow-wrap:anywhere}#unjoinedApp .uj-gallery img{width:200px;height:180px;object-fit:contain;background:#F3FAF4;border:1px solid var(--line);border-radius:8px}@media(max-width:850px){#unjoinedApp #ujCards{grid-template-columns:repeat(2,1fr)}#unjoinedApp .uj-full-grid{grid-template-columns:repeat(2,1fr)}#unjoinedApp .uj-body{padding:12px}#unjoinedApp .uj-header{padding:18px}#unjoinedApp .uj-filters label{flex:1;min-width:140px}}@media(max-width:480px){#unjoinedApp .uj-full-grid{grid-template-columns:1fr}#unjoinedApp .uj-header h1{font-size:23px}#unjoinedApp .uj-card{padding:12px}}
