// LIFE_UNJOINED_V3
(() => {
'use strict';
const root=document.getElementById('unjoinedApp'); if(!root||root.dataset.ready)return; root.dataset.ready='1';
const $=s=>root.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Role is obtained from the signed-in server session; failures stay masked.
let systemManager=false;
function maskPhone(value){const s=String(value??'');if(!s||systemManager)return s;const digits=s.replace(/\D/g,'');if(!digits)return s;return digits.length>6?digits.slice(0,3)+'*'.repeat(digits.length-6)+digits.slice(-3):'*'.repeat(digits.length);}
function maskTextNumbers(value){const s=String(value??'');return systemManager?s:s.replace(/\+?\d[\d ()-]{5,}\d/g,part=>{const n=part.replace(/\D/g,'');return n.length>=7&&n.length<=15&&!/^\d{4}-\d{2}-\d{2}/.test(part)?maskPhone(part):part;});}
function isPhoneField(field){return /mobile|phone|whatsapp|telephone|contact.*(number|no)/i.test(String(field||''));}
function displayValue(field,value){if(Array.isArray(value))return JSON.stringify(value.map(row=>sanitizeObject(row)));if(value&&typeof value==='object')return JSON.stringify(sanitizeObject(value));return isPhoneField(field)?maskPhone(value):maskTextNumbers(value);}
function sanitizeObject(value){if(Array.isArray(value))return value.map(sanitizeObject);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,v])=>[key,typeof v==='object'?sanitizeObject(v):displayValue(key,v)]));return maskTextNumbers(value);}
function numberHTML(value){const shown=maskPhone(value||'—');return `<span class="uj-mobile" title="${esc(shown)}">${esc(shown)}</span>`;}
async function verifyMaskingRole(){
  systemManager=false;
  const hasManager=roles=>Array.isArray(roles)&&roles.some(r=>String(r&&typeof r==='object'?r.role:r).trim()==='System Manager');
  try{
    const bootRoles=[
      ...(Array.isArray(frappe.user_roles)?frappe.user_roles:[]),
      ...(Array.isArray(frappe.boot?.user?.roles)?frappe.boot.user.roles:[])
    ];
    systemManager=hasManager(bootRoles);
    if(!systemManager){
      let user=frappe.session?.user||frappe.boot?.user?.name||'';
      if(!user)user=await api('frappe.auth.get_logged_user',{});
      if(user&&user!=='Guest'){
        try{systemManager=hasManager(await api('frappe.core.doctype.user.user.get_roles',{uid:user}));}catch(e){}
        if(!systemManager){
          try{
            const doc=await api('frappe.client.get',{doctype:'User',name:user});
            systemManager=doc?.name===user&&hasManager(doc.roles);
          }catch(e){}
        }
      }
    }
  }catch(e){void 0;}
  $('#ujMaskNote').textContent=systemManager?'System Manager · full numbers in list, hover, details, print and Excel':'Contact numbers are masked on screen, hover, print and Excel';
}

