function followEditor(){if(!session)return;const p=session.form||session.defaults;$('#ujFollowPane').innerHTML=`<div class="uj-follow-hero">${photoHTML(p.custom_client_photo_attach||session.sourcePhoto,true)}<div><small>UNJOINED CLIENT FORM</small><h3>${esc(maskTextNumbers(p.client_name||session.sourceDoc?.name||'Follow-up'))}</h3><p>${session.form?'Editing saved follow-up record':'New follow-up record'}${session.form?' · '+esc(maskTextNumbers(session.form.name)):''}</p></div></div><p class="uj-help">Save these fields to Unjoined Client Form.</p>${session.lookupError?'<p class="uj-error">'+esc(session.lookupError)+'</p>':''}<div id="ujLegacy"></div><form id="ujEditForm"><div class="uj-edit-grid">${followFields.map(f=>fieldInput(f,p[f.fieldname])).join('')}<label class="uj-wide">Client Photo<input id="ujPhotoFile" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · up to 10 MB</small></label></div><div class="uj-save-bar"><span id="ujSaveState" role="status">${session.lookupError?'Record lookup failed; saving is blocked until reloaded.':session.form?'Ready to edit':'Not saved yet'}</span><button type="submit" id="ujSaveForm" class="uj-primary" ${session.lookupError?'disabled':''}>Save Follow-up</button></div></form>`;$('#ujEditForm').addEventListener('submit',e=>{e.preventDefault();saveFollow();});$('#ujEditForm').addEventListener('input',()=>{dirty=true;$('#ujSaveState').textContent='Unsaved changes';});showNextFollow();}
