async function lookupFollow(c,doc){session={c,sourceDoc:doc,sourcePhoto:doc.custom_client_photo_attach||doc.image,form:null,defaults:{client_name:doc[c.name]||doc.name,branch:doc[c.branch]||doc.branch_name||'',contact_number:doc[c.mobile]||doc.mobile||doc.phone||'',treatment:doc[c.category]||'',visited_date:(c.key==='clients'||c.key==='leads')?String(doc[c.date]||'').slice(0,10):'',status:'',remarks:'',follow_up:'',calling_date:currentDate()},lookupError:'',legacy:[]};if(c.dt===FORM_DT){session.form=doc;followEditor();return;}
