async function saveFollow(){if(saving||!session||session.lookupError)return;const form=$('#ujEditForm');if(!form.reportValidity())return;const ctx=session;const values={};form.querySelectorAll('[data-form-field]').forEach(el=>{if(!systemManager&&isPhoneField(el.dataset.formField))return;values[el.dataset.formField]=el.value.trim();});if(!systemManager)values.contact_number=ctx.form?ctx.form.contact_number:(ctx.defaults.contact_number||'');if(values.status==='Follow Up Scheduled'&&!values.next_follow_up_scheduled_date){$('#ujSaveState').textContent='Choose the next follow-up date.';return;}if(!systemManager){const original=ctx.form||ctx.defaults;for(const field of Object.keys(values)){if(!isPhoneField(field)&&values[field]===maskTextNumbers(original[field]??''))values[field]=original[field]??'';}}const file=$('#ujPhotoFile')?.files[0];if(file&&(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)){$('#ujSaveState').textContent='Choose a JPEG, PNG or WebP image below 10 MB.';return;}saving=true;$('#ujSaveForm').disabled=true;$('#ujClose').disabled=true;const status=$('#ujSaveState');status.textContent='Saving…';let recordSaved=false;try{let doc=ctx.form?JSON.parse(JSON.stringify(ctx.form)):{doctype:FORM_DT};Object.assign(doc,values);if(ctx.c.dt!==FORM_DT){const hash=await sourceKey(ctx.c.dt,ctx.sourceDoc.name);if(doc.custom_source_document&&(doc.custom_source_doctype!==ctx.c.dt||doc.custom_source_document!==ctx.sourceDoc.name))throw new Error('This form is linked to a different source.');doc.custom_source_doctype=ctx.c.dt;doc.custom_source_document=ctx.sourceDoc.name;doc.custom_source_key=hash;if(!ctx.form)doc.client_full_name=String(values.client_name).slice(0,65)+' · UJ-'+hash.slice(0,16);if(ctx.c.dt==='Patient')doc.custom_linked_client=ctx.sourceDoc.name;if(ctx.c.dt==='Lead')doc.custom_linked_lead=ctx.sourceDoc.name;if(ctx.c.dt==='Patient Appointment'&&ctx.sourceDoc.patient)doc.custom_linked_client=ctx.sourceDoc.patient;}
