function api(method,args){return new Promise((resolve,reject)=>frappe.call({method,args,callback:r=>r.exc?reject(new Error('ERP request failed.')):resolve(r.message),error:r=>reject(new Error(r?.responseJSON?.exception||r?.statusText||'ERP access or network error.'))}));}
function url(v){try{const u=new URL(v,location.origin);return u.origin===location.origin&&['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function date(v){if(!v)return '—';const s=String(v),m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return esc(s);const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];let out=m[3]+'-'+months[+m[2]-1]+'-'+m[1].slice(2);const t=s.match(/[ T](\d{2}):(\d{2})/);if(t)out+=' '+(+t[1]%12||12)+':'+t[2]+' '+(+t[1]>=12?'pm':'am');return out;}
function currentDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function filters(c){let f=c.base.map(x=>x.slice());const b=$('#ujBranch').value;if(b)f.push([c.branch,'=',b]);else f.push([c.branch,'!=','Testing Branch']);if(c.key==='forms'&&$('#ujFollowStatus').value)f.push(['status','=',$('#ujFollowStatus').value]);const field=$('#ujBasis').value==='created'?'creation':c.date;const from=$('#ujFrom').value,to=$('#ujTo').value;if(from)f.push([field,'>=',from]);if(to){const d=new Date(to+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);f.push([field,'<',d.toISOString().slice(0,10)]);}return f;}
