async function page(c,token){const s=state[c.key];try{const args={doctype:c.dt,filters:filters(c),or_filters:ors(c)};const results=await Promise.all([api('frappe.client.get_list',{...args,fields:c.fields,limit_start:s.page*20,limit_page_length:20,order_by:'creation desc, name desc'}),api('frappe.client.get_list',{...args,fields:['count(name) as total'],limit_page_length:1})]);if(token!==generation)return;s.rows=results[0]||[];if(c.dt!==FORM_DT&&s.rows.length){try{const followups=await api('frappe.client.get_list',{doctype:FORM_DT,filters:{custom_source_doctype:c.dt,custom_source_document:['in',s.rows.map(r=>r.name)]},fields:['name','custom_source_document','custom_client_photo_attach','status'],limit_page_length:100});for(const fu of followups)followCache.set(sourceId(c.dt,fu.custom_source_document),fu);}catch(e){void 0;}}s.count=Number(results[1]?.[0]?.total)||0;s.error=null;}catch(e){if(token!==generation)return;s.rows=[];s.count=0;s.error=e.message;}}
async function load(){if(busy)return;if($('#ujFrom').value&&$('#ujTo').value&&$('#ujFrom').value>$('#ujTo').value){$('#ujNotice').textContent='From date must be before To date.';return;}busy=true;loaded=false;controls();const token=++generation;$('#ujNotice').textContent='Loading permitted ERP records…';configs.forEach(c=>state[c.key].page=0);await Promise.all(configs.map(c=>page(c,token)));busy=false;loaded=true;render();controls();$('#ujNotice').textContent='Loaded '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:true})+'. Counts are section-wise; the same person may have a Client and Lead record. '+(configs.some(c=>state[c.key].error)?'Some sections could not be read; see their errors.':'');}
