function media(files){return files.map(f=>{const u=url(f.file_url);if(!u)return '';const img=/\.(png|jpe?g|gif|webp|bmp|avif)(?:[?#]|$)/i.test(u);return `<a href="${esc(u)}" target="_blank" rel="noopener">${img?`<img loading="lazy" src="${esc(u)}" alt="${esc(maskTextNumbers(f.file_name||'Attached image'))}">`:''}<span>${esc(maskTextNumbers(f.file_name||'Attachment'))}</span></a>`;}).join('')||'<div class="uj-photo-empty">Image not attached</div>';}
function documentHTML(dt,doc){let out=`<h3>${esc(dt)} · ${esc(maskTextNumbers(doc.name))}</h3><div class="uj-full-grid">`;for(const f of META[dt]||[]){if(/Section Break|Column Break|Tab Break|HTML|Button|Heading|Password/.test(f.fieldtype)||f.permlevel>0)continue;const v=doc[f.fieldname];if(v===undefined||v===null||v==='')continue;if(Array.isArray(v)){out+=`<div class="uj-wide"><b>${esc(f.label||f.fieldname)}</b>${childTable(v)}</div>`;}else{out+=`<div><b>${esc(f.label||f.fieldname)}</b><span>${/Date/.test(f.fieldtype)?date(v):esc(displayValue(f.fieldname,v))}</span></div>`;}}return out+'</div>';}
function childTable(rows){const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(k=>!['doctype','owner','modified_by','creation','modified','docstatus','parent','parentfield','parenttype','name','idx'].includes(k));return '<div class="uj-scroll"><table><thead><tr>'+keys.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td>'+esc(displayValue(k,r[k]))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
async function files(dt,id){try{return {rows:await api('frappe.client.get_list',{doctype:'File',filters:{attached_to_doctype:dt,attached_to_name:id},fields:['name','file_name','file_url'],limit_page_length:1000}),error:''};}catch(e){return {rows:[],error:'Attachments could not be listed: '+e.message};}}
let detailToken=0;
async function detail(c,id,openFollow=false){if(saving)return;if(dirty&&!confirm('Discard unsaved follow-up changes?'))return;dirty=false;session=null;const token=++detailToken,dlg=$('#ujDialog');if(!dlg.open)dlg.showModal();detailTab(openFollow?'follow':'record');$('#ujFollowPane').innerHTML='<p>Loading follow-up form…</p>';$('#ujDetails').innerHTML='<p>Loading full record and attached images…</p>';try{const doc=await api('frappe.client.get',{doctype:c.dt,name:id});if(token!==detailToken)return;await lookupFollow(c,doc);if(token!==detailToken)return;const parts=[{dt:c.dt,doc}];let warning='';if(c.dt==='Patient Appointment'&&doc.patient){try{parts.push({dt:'Patient',doc:await api('frappe.client.get',{doctype:'Patient',name:doc.patient})});}catch(e){warning+='Linked client: '+e.message+' ';}}if(c.dt==='Lead'){try{const clients=await api('frappe.client.get_list',{doctype:'Patient',filters:{custom_lead:id},fields:['name'],limit_page_length:100});for(const p of clients)parts.push({dt:'Patient',doc:await api('frappe.client.get',{doctype:'Patient',name:p.name})});}catch(e){warning+='Linked clients could not be read: '+e.message;}}
if(c.dt===FORM_DT&&doc.custom_linked_client){try{parts.push({dt:'Patient',doc:await api('frappe.client.get',{doctype:'Patient',name:doc.custom_linked_client})});}catch(e){warning+='Linked client could not be read: '+e.message;}}if(c.dt!==FORM_DT&&session?.form)parts.push({dt:FORM_DT,doc:session.form});let html=warning?'<p class="uj-error">'+esc(warning)+'</p>':'';for(const p of parts){const attached=await files(p.dt,p.doc.name);const direct=(META[p.dt]||[]).filter(f=>/Attach/.test(f.fieldtype)&&p.doc[f.fieldname]).map(f=>({file_name:f.label||f.fieldname,file_url:p.doc[f.fieldname]}));const seen=new Set(),all=[...direct,...attached.rows].filter(f=>{if(seen.has(f.file_url))return false;seen.add(f.file_url);return true;});html+=photoHTML(p.doc.custom_client_photo_attach||p.doc.image,true)+documentHTML(p.dt,p.doc)+'<h4>Attached images & documents</h4>'+(attached.error?'<p class="uj-error">'+esc(attached.error)+'</p>':'')+'<div class="uj-gallery">'+media(all)+'</div>';}
if(token===detailToken)$('#ujDetails').innerHTML=html;}catch(e){if(token===detailToken){$('#ujDetails').innerHTML='<p class="uj-error">'+esc(e.message)+'</p>';$('#ujFollowPane').innerHTML='<p class="uj-error">'+esc(e.message)+'</p>';}}}
async function allRows(c){const rows=[];for(let start=0;;start+=500){$('#ujNotice').textContent='Preparing '+c.title+' · '+rows.length+' records…';const batch=await api('frappe.client.get_list',{doctype:c.dt,fields:c.fields,filters:filters(c),or_filters:ors(c),limit_start:start,limit_page_length:500,order_by:'creation desc, name desc'});rows.push(...batch);if(batch.length<500)break;}return rows;}
// XLSX is built locally as an OOXML ZIP. No external script or CDN is needed.
const enc=new TextEncoder(),crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc(b){let n=0xffffffff;for(const x of b)n=crcTable[(n^x)&255]^(n>>>8);return(n^0xffffffff)>>>0;}
function zip(items){let off=0,body=[],central=[];for(const [name,str] of items){const n=enc.encode(name),b=enc.encode(str),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,crc(b),true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);h.set(n,30);const c=new Uint8Array(46+n.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint32(16,crc(b),true);d.setUint32(20,b.length,true);d.setUint32(24,b.length,true);d.setUint16(28,n.length,true);d.setUint32(42,off,true);c.set(n,46);body.push(h,b);central.push(c);off+=h.length+b.length;}const size=central.reduce((s,b)=>s+b.length,0),e=new Uint8Array(22),v=new DataView(e.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,items.length,true);v.setUint16(10,items.length,true);v.setUint32(12,size,true);v.setUint32(16,off,true);return new Blob([...body,...central,e],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
function xml(v){return String(v??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function sheet(rows){return '<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+rows.map((r,i)=>'<row r="'+(i+1)+'">'+r.map(v=>'<c t="inlineStr"><is><t xml:space="preserve">'+xml(v)+'</t></is></c>').join('')+'</row>').join('')+'</sheetData></worksheet>';}
function workbook(sheets){const ns='http://schemas.openxmlformats.org/package/2006/relationships';let items=[['[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+sheets.map((s,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>'],['_rels/.rels','<Relationships xmlns="'+ns+'"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+sheets.map((s,i)=>'<sheet name="'+xml(s.name)+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join('')+'</sheets></workbook>'],['xl/_rels/workbook.xml.rels','<Relationships xmlns="'+ns+'">'+sheets.map((s,i)=>'<Relationship Id="rId'+(i+1)+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+(i+1)+'.xml"/>').join('')+'</Relationships>']];sheets.forEach((s,i)=>items.push(['xl/worksheets/sheet'+(i+1)+'.xml',sheet(s.rows)]));return zip(items);}
async function output(key,print){if(busy||!loaded)return;const selected=key==='all'?configs:configs.filter(c=>c.key===key);if(selected.some(c=>state[c.key].error)){alert('Resolve the section access errors before exporting.');return;}const win=print?window.open('','_blank'):null;if(print&&!win){alert('Allow popups for printing.');return;}if(win)win.document.body.textContent='Preparing all filtered records…';busy=true;controls();try{const batches=[];for(const c of selected)batches.push({c,rows:await allRows(c)});if(print){let html='<h1>LIFE · Unjoined Data</h1><p>'+esc($('#ujFrom').value||'All dates')+' to '+esc($('#ujTo').value||'All dates')+' · '+esc($('#ujBranch').value||'All permitted branches')+' · '+esc($('#ujBasis').selectedOptions[0].text)+' · '+esc(maskTextNumbers($('#ujSearch').value))+'</p>';for(const {c,rows} of batches)html+='<h2>'+esc(c.title)+' ('+rows.length+')</h2><table><thead><tr>'+['ID','Name','Mobile','Branch','Category',$('#ujBasis').value==='created'?'Created date':c.dateLabel,'Status'].map(v=>'<th>'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+['name',c.name,c.mobile,c.branch,c.category,$('#ujBasis').value==='created'?'creation':c.date,c.status].map(field=>'<td>'+esc(displayValue(field,r[field]))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';win.document.write('<!doctype html><html><head><title>Unjoined Data</title><style>@page{size:A4 landscape;margin:12mm}body{font:11px Arial;color:#152418}h1,h2{color:#1b5e20}table{border-collapse:collapse;width:100%;margin-bottom:24px}td,th{border:1px solid #dce9de;padding:5px;word-break:break-word;text-align:left}thead{display:table-header-group}tr{break-inside:avoid}h2{break-after:avoid}</style></head><body>'+html+'</body></html>');win.document.close();win.focus();win.print();}else{const sheets=batches.map(({c,rows})=>({name:c.key,rows:[c.fields.map(f=>META[c.dt].find(x=>x.fieldname===f)?.label||f),...rows.map(r=>c.fields.map(f=>displayValue(f,r[f]??'')))]}));sheets.push({name:'Filters',rows:[['From',$('#ujFrom').value],['To',$('#ujTo').value],['Branch',$('#ujBranch').value||'All permitted branches'],['Date basis',$('#ujBasis').value],['Search',maskTextNumbers($('#ujSearch').value)],['Generated',new Date().toISOString()],['Notes','Section counts may overlap. Export includes all filtered list records; full record and child tables are available through Full details & images.']]});const u=URL.createObjectURL(workbook(sheets)),a=document.createElement('a');a.href=u;a.download='LIFE_Unjoined_Data_'+currentDate()+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}$('#ujNotice').textContent='Prepared '+batches.reduce((n,b)=>n+b.rows.length,0)+' filtered records.';}catch(e){if(win)win.close();$('#ujNotice').textContent='Export / print failed: '+e.message;}finally{busy=false;controls();}}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)return activateTab(b.dataset.tab);if(b.dataset.detailTab)return detailTab(b.dataset.detailTab);if(b.dataset.edit)return detail(configs.find(c=>c.key===b.dataset.edit),b.dataset.id,true);if(b.id==='ujApply')return load();if(b.id==='ujReset'){$('#ujFrom').value='';$('#ujTo').value='';$('#ujBranch').value='';$('#ujSearch').value='';$('#ujFollowStatus').value='';return load();}if(b.dataset.detail)return detail(configs.find(c=>c.key===b.dataset.detail),b.dataset.id);if(b.dataset.export)return output(b.dataset.export,false);if(b.dataset.print)return output(b.dataset.print,true);if(b.id==='ujClose'){if(saving)return;if(dirty&&!confirm('Discard unsaved follow-up changes?'))return;detailToken++;dirty=false;session=null;$('#ujDialog').close();}if(b.id==='ujPrintDetail'){const w=window.open('','_blank');if(!w)return alert('Allow popups for printing.');w.document.write('<!doctype html><html><head><title>Full client details</title><style>body{font:12px Arial}b{display:block}img{max-width:200px;max-height:200px}.uj-full-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.uj-wide{grid-column:1/-1}table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:4px}.uj-gallery{display:flex;flex-wrap:wrap;gap:12px}.uj-gallery a{display:grid}</style></head><body>'+$('#ujDetails').innerHTML+'</body></html>');w.document.close();await Promise.all(Array.from(w.document.images).map(im=>im.complete?Promise.resolve():new Promise(res=>{im.onload=res;im.onerror=res;setTimeout(res,8000);})));w.print();}if(b.dataset.page&&!busy){const c=configs.find(c=>c.key===b.dataset.page);state[c.key].page+=Number(b.dataset.step);busy=true;controls();await page(c,generation);busy=false;render();controls();}});
root.querySelectorAll('.uj-filters input,.uj-filters select').forEach(el=>el.addEventListener('change',()=>{loaded=false;controls();$('#ujNotice').textContent='Filters changed. Click Apply to refresh data.';}));$('#ujSearch').addEventListener('input',()=>{loaded=false;controls();});$('#ujSearch').addEventListener('keydown',e=>{if(e.key==='Enter')load();});
$('#ujSections').innerHTML=configs.map(c=>`<section id="uj-${c.key}" role="tabpanel" hidden><div class="uj-section-head"><div><h2>${esc(c.title)} <span class="uj-count">0</span></h2><small>Date filter: <span class="uj-date-label">${esc(c.dateLabel)}</span></small></div><div><button data-export="${c.key}">Export Excel</button><button data-print="${c.key}">Print / Save PDF</button></div></div><div class="uj-scroll"><table><thead><tr><th>#</th><th>Client / Lead</th><th>Mobile / Alternate</th><th>Branch</th><th>Category</th><th>Date</th><th>Status</th><th>Details / Images</th></tr></thead><tbody></tbody></table></div><div class="uj-paging"></div></section>`).join('');
async function init(){if(!window.frappe||frappe.session?.user==='Guest'){$('#ujNotice').innerHTML='Please <a href="/login?redirect-to=%2Funjoined-data">sign in</a> to view Unjoined Data.';root.querySelectorAll('button').forEach(e=>e.disabled=true);return;}await verifyMaskingRole();try{const branches=await api('frappe.client.get_list',{doctype:'Branch',fields:['name'],limit_page_length:1000,order_by:'name asc'});branchNames=branches.filter(b=>b.name!=='Testing Branch').map(b=>b.name);$('#ujBranch').innerHTML='<option value="">All permitted branches</option>'+branches.filter(b=>b.name!=='Testing Branch').map(b=>'<option>'+esc(b.name)+'</option>').join('');}catch(e){$('#ujNotice').textContent='Branch list unavailable: '+e.message;}await load();}init();
